    def all_history_consumptions(
        self, billing_account: str
    ) -> t.AsyncIterator[models.TelephonyHistoryConsumption]:
        """all_history_consumptions iterates over GET /v1/telephony/{billingAccount}/historyConsumption (List billed consumptions).

        It lists the IDs with list_history_consumptions, then gets each object with get_history_consumption,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop. Use it with ``async for``.

        Args:
            billing_account: The name of your billingAccount

        The two calls require the IAM action voip:apiovh:historyConsumption/get.
        """
        return self._each(
            lambda: self.list_history_consumptions(
                billing_account,
            ),
            lambda listed_id: self.get_history_consumption(billing_account, listed_id),
        )

