    def all_line_traffic_extracts(
        self, billing_account: str, service_name: str
    ) -> t.AsyncIterator[models.TelephonyTrafficExtract]:
        """all_line_traffic_extracts iterates over GET /v1/telephony/{billingAccount}/line/{serviceName}/trafficExtracts (List traffic extracts).

        It lists the IDs with list_line_traffic_extracts, then gets each object with get_line_traffic_extracts,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop. Use it with ``async for``.

        Args:
            billing_account: The name of your billingAccount
            service_name: the serviceName path parameter

        The two calls require the IAM action voip:apiovh:line/trafficExtracts/get.
        """
        return self._each(
            lambda: self.list_line_traffic_extracts(
                billing_account,
                service_name,
            ),
            lambda listed_id: self.get_line_traffic_extracts(
                billing_account, service_name, listed_id
            ),
        )

